MEMBER_SCRIPT = [===[-- STA2E 0.5: visible physical controls and persistent component identity.
memory = {}
display = {dialOpen=false}
function onLoad(saved)
    if saved and saved ~= "" then
        local ok, value = pcall(JSON.decode, saved)
        if ok and type(value) == "table" then memory = value end
    end
    if memory.role == "model" then self.interactable = false; self.setLock(true) end
    STA2E_DrawButtons()
    Wait.frames(function() Global.call("STA2E_Register", {object=self}) end, 2)
end
function onSave() return JSON.encode(memory) end
function STA2E_SetMemory(value)
    memory = value
    self.script_state = JSON.encode(memory)
    STA2E_DrawButtons()
end
function STA2E_SetDisplay(value)
    display = value or {dialOpen=false}
    STA2E_DrawButtons()
end
function STA2E_UI(player, value, id)
    Global.call("STA2E_Command", {object=self, color=player.color, command=id})
end
local function send(color, command)
    Global.call("STA2E_Command", {object=self, color=color, command=command})
end
local function add(callback, label, x, z, width, color, height, fontSize)
    self.createButton({function_owner=self,click_function=callback,label=label,position={x,0.28,z},
        width=width or 240,height=height or 92,font_size=fontSize or 42,color=color or {0.12,0.28,0.42,0.82},font_color={1,1,1},tooltip=label})
end
function STA2E_DrawButtons()
    self.clearButtons()
    if memory.role == "card" then
        local dialOpen=memory.state and memory.state.dialOpen==true
        add("STA2E_Deploy","DEPLOY",-0.62,-1.78,500,{0.08,0.38,0.25,0.88})
        add("STA2E_OpenDial",dialOpen and "CLOSE DIAL" or "OPEN DIAL",0.62,-1.78,500,{0.12,0.28,0.42,0.88})
    elseif memory.role == "upgrade" or memory.role == "fleetCard" then
        add("STA2E_Manage","MANAGE",0,-1.55,330,{0.12,0.28,0.42,0.75},80,34)
    elseif memory.role == "dial" then
        -- Maneuver controls use color-scoped XML assembled by Global.
        -- Physical buttons cannot keep a planned maneuver secret.
    end
end
function STA2E_Deploy(_,color) send(color,"deploy") end
function STA2E_OpenDial(_,color) send(color,"open_dial") end
function STA2E_Manage(_,color) Global.call("STA2E_ManageCard",{object=self,color=color}) end
function STA2E_Lock(_,color) send(color,"lock") end
function STA2E_Change(_,color) send(color,"change") end
function STA2E_Reveal(_,color) send(color,"reveal") end
function STA2E_Execute(_,color) send(color,"move") end
function STA2E_Finish(_,color) send(color,"finish") end
function STA2E_Undo(_,color) send(color,"undo") end
function STA2E_Action_EVA(_,color) send(color,"action_EVA") end
function STA2E_Action_SCN(_,color) send(color,"action_SCN") end
function STA2E_Action_BS(_,color) send(color,"action_BS") end
function STA2E_Action_TL(_,color) send(color,"action_TL") end
function STA2E_Action_CLK(_,color) send(color,"action_CLK") end
function STA2E_Action_ECHO(_,color) send(color,"action_ECHO") end
function STA2E_Move_CA3(_,c) send(c,"select_CA3") end
function STA2E_NextPhase(_,color) Global.call("STA2E_PhaseFromDial",{color=color}) end
function STA2E_NoOp() end
function STA2E_Move_S1(_,c) send(c,"select_S1") end
function STA2E_Move_BL1(_,c) send(c,"select_BL1") end
function STA2E_Move_BR1(_,c) send(c,"select_BR1") end
function STA2E_Move_S2(_,c) send(c,"select_S2") end
function STA2E_Move_BL2(_,c) send(c,"select_BL2") end
function STA2E_Move_BR2(_,c) send(c,"select_BR2") end
function STA2E_Move_TL3(_,c) send(c,"select_TL3") end
function STA2E_Move_S3(_,c) send(c,"select_S3") end
function STA2E_Move_TR3(_,c) send(c,"select_TR3") end
function STA2E_Move_BL3(_,c) send(c,"select_BL3") end
function STA2E_Move_BR3(_,c) send(c,"select_BR3") end
function STA2E_Move_S4(_,c) send(c,"select_S4") end
function STA2E_Move_S5(_,c) send(c,"select_S5") end
function STA2E_Move_R1(_,c) send(c,"select_R1") end
function STA2E_Move_R2(_,c) send(c,"select_R2") end
