STA2E = {}
function STA2E.EnsureMoveDefs()
    STA2E.MoveDefs = STA2E.MoveDefs or {
        R180 = {rotate = 180},
        R90L = {rotate = -90},
        R90R = {rotate = 90},

        S1 = {forward = 3.10, side = 0, rotate = 0},
        S2 = {forward = 4.60, side = 0, rotate = 0},
        S3 = {forward = 6.30, side = 0, rotate = 0},
        S4 = {forward = 7.90, side = 0, rotate = 0},
        S5 = {forward = 9.40, side = 0, rotate = 0},
        S6 = {forward = 10.90, side = 0, rotate = 0},

        BL1 = {forward = 4.10, side = 1.65, rotate = -45},
        BL2 = {forward = 5.28, side = 2.08, rotate = -45},
        BL3 = {forward = 6.15, side = 2.45, rotate = -45},
        BL4 = {forward = 7.35, side = 2.73, rotate = -45},

        BR1 = {forward = 4.10, side = -1.65, rotate = 45},
        BR2 = {forward = 5.28, side = -2.08, rotate = 45},
        BR3 = {forward = 6.15, side = -2.45, rotate = 45},
        BR4 = {forward = 7.35, side = -2.73, rotate = 45},

        TL1 = {forward = 2.10, side = 2.10, rotate = -90},
        TL2 = {forward = 3.20, side = 3.20, rotate = -90},
        TL3 = {forward = 4.30, side = 4.20, rotate = -90},

        TR1 = {forward = 2.10, side = -2.10, rotate = 90},
        TR2 = {forward = 3.20, side = -3.20, rotate = 90},
        TR3 = {forward = 4.30, side = -4.20, rotate = 90},

        EcoL1_F = {forward = 0.83, side = 3.05, rotate = 0},
        EcoL1_S = {forward = 0.00, side = 3.05, rotate = 0},
        EcoL1_B = {forward = -0.83, side = 3.05, rotate = 0},
        EcoL2_F = {forward = 0.83, side = 4.60, rotate = 0},
        EcoL2_S = {forward = 0.00, side = 4.60, rotate = 0},
        EcoL2_B = {forward = -0.83, side = 4.60, rotate = 0},

        EcoR1_F = {forward = 0.83, side = -3.05, rotate = 0},
        EcoR1_S = {forward = 0.00, side = -3.05, rotate = 0},
        EcoR1_B = {forward = -0.83, side = -3.05, rotate = 0},
        EcoR2_F = {forward = 0.83, side = -4.60, rotate = 0},
        EcoR2_S = {forward = 0.00, side = -4.60, rotate = 0},
        EcoR2_B = {forward = -0.83, side = -4.60, rotate = 0},
    }

    -- Extra movement families found in the dial database.
    local reverse = {3.10, 4.60, 6.30, 7.90, 9.40, 10.90}
    for i, distance in ipairs(reverse) do
        STA2E.MoveDefs["R" .. i] = STA2E.MoveDefs["R" .. i] or {forward = -distance, side = 0, rotate = 0}
        STA2E.MoveDefs["GL" .. i] = STA2E.MoveDefs["GL" .. i] or {forward = 0, side = distance, rotate = 0}
        STA2E.MoveDefs["GR" .. i] = STA2E.MoveDefs["GR" .. i] or {forward = 0, side = -distance, rotate = 0}
    end

    -- Borg spin maneuvers move straight, then rotate 90 degrees.
    for i, distance in ipairs(reverse) do
        STA2E.MoveDefs["SL" .. i] = STA2E.MoveDefs["SL" .. i] or {forward = distance, side = 0, rotate = 90, finishRotateOnly = true}
        STA2E.MoveDefs["SR" .. i] = STA2E.MoveDefs["SR" .. i] or {forward = distance, side = 0, rotate = -90, finishRotateOnly = true}
    end

    -- Come About: first-pass implementation. Tune later with your actual templates.
    STA2E.MoveDefs.CA1 = STA2E.MoveDefs.CA1 or {forward = 3.10, side = 0, rotate = 180}
    STA2E.MoveDefs.CA2 = STA2E.MoveDefs.CA2 or {forward = 4.60, side = 0, rotate = 180}
    STA2E.MoveDefs.CA3 = STA2E.MoveDefs.CA3 or {forward = 6.30, side = 0, rotate = 180}
    STA2E.MoveDefs.CA4 = STA2E.MoveDefs.CA4 or {forward = 7.90, side = 0, rotate = 180}

    -- DS9 / station-style entries from the dial database.
    STA2E.MoveDefs.STOP0 = STA2E.MoveDefs.STOP0 or {forward = 0, side = 0, rotate = 0}
    STA2E.MoveDefs.ROTL0 = STA2E.MoveDefs.ROTL0 or {rotate = -90}
    STA2E.MoveDefs.ROTR0 = STA2E.MoveDefs.ROTR0 or {rotate = 90}
    STA2E.MoveDefs.PIVOTL0 = STA2E.MoveDefs.PIVOTL0 or {rotate = -45}
    STA2E.MoveDefs.PIVOTR0 = STA2E.MoveDefs.PIVOTR0 or {rotate = 45}
    STA2E.MoveDefs.DL1 = STA2E.MoveDefs.DL1 or {forward = -3.10, side = 3.10, rotate = 0}
    STA2E.MoveDefs.DR1 = STA2E.MoveDefs.DR1 or {forward = -3.10, side = -3.10, rotate = 0}
    STA2E.MoveDefs.DL2 = STA2E.MoveDefs.DL2 or {forward = -4.60, side = 4.60, rotate = 0}
    STA2E.MoveDefs.DR2 = STA2E.MoveDefs.DR2 or {forward = -4.60, side = -4.60, rotate = 0}
end


STA2E.EnsureMoveDefs()
MOVE_DEFS = STA2E.MoveDefs
-- STA2E 0.4: persistent ship-instance development slice.
-- CATALOG, MEMBER_SCRIPT, GALAXY_DIAL and MOVE_DEFS are bundled by build.mjs.
STA2E = {ships={}, pending={}, imports={}, ready=false}
local function copy(value) return JSON.decode(JSON.encode(value)) end
local function decode(text)
    local ok, value = pcall(JSON.decode, text or "")
    if ok and type(value) == "table" then return value end
    return nil
end
local function tell(color, message)
    if color == "Blue" or color == "Red" or color == "Black" then
        broadcastToColor(message, color, {0.65,0.85,1})
    else print(message) end
end
local function xml(text)
    return tostring(text or ""):gsub("&", "&amp;"):gsub('"', "&quot;"):gsub("<", "&lt;"):gsub(">", "&gt;")
end
local function obj(guid) return guid and getObjectFromGUID(guid) or nil end
local function own(color) return color == "Blue" or color == "Red" end
local function nextId()
    STA2E.game.nextId = STA2E.game.nextId + 1
    return "sta2e-" .. tostring(STA2E.game.nextId)
end
local function metadata(object) return object and object.getTable("memory") or nil end
local function member(s, role)
    local object = obj(s.refs[role])
    local m = metadata(object)
    local roleMatches=m and (m.role==role or (m.role=="baseModel" and (role=="base" or role=="model")))
    if roleMatches and m.instanceId == s.instanceId and m.cardGUID == s.cardGUID then return object end
    return nil
end
local function commit(s)
    local card = obj(s.cardGUID)
    if card then card.call("STA2E_SetMemory", copy(s)) end
end
local function maneuverReference(id)
    return CATALOG_DATA.maneuverReferences and CATALOG_DATA.maneuverReferences[id] or nil
end
local function complete(s)
    return member(s,"base") and member(s,"model") and member(s,"dial") and (not maneuverReference(s.definitionId) or member(s,"reference"))
end
local ACTION_KEYS={evade="EVA",scan="SCN",battlestations="BS",["target-lock"]="TL",cloak="CLK",["sensor-echo"]="ECHO",regenerate="REG"}
local function definition(id)
    local ship=SHIP_DEFINITIONS[id]
    return ship and SHIP_DATA.classes[ship.profile] or nil,ship
end
local function capabilities(id)
    local class,ship=definition(id);local actions={}
    for _,name in ipairs(ship and ship.actions or {}) do if ACTION_KEYS[name] then table.insert(actions,ACTION_KEYS[name]) end end
    return {dialId=ship and ship.class or "Unknown",actions=actions,arcs=class and {class.arc} or {},prototype=ship==nil}
end
local function dialFor(s) local class=definition(s.definitionId);return class and class.dial or GALAXY_DIAL end
local function shipFor(object)
    local m = metadata(object)
    if not m then return nil end
    local s = STA2E.ships[m.instanceId]
    if not s then return nil end
    if m.role == "card" then
        if s.cardGUID == object.getGUID() then return s end
    elseif m.role=="baseModel" then
        if member(s,"base")==object then return s end
    elseif member(s, m.role) == object then return s end
    return nil
end
local function button(id, text, x, y, color)
    return '<Button id="'..id..'" onClick="STA2E_UI" position="'..x..' '..y..' 0" width="205" height="50" fontSize="18" color="'..(color or '#284A66')..'">'..xml(text)..'</Button>'
end
local function maneuverLabel(s,key)
    local entry=maneuver and maneuver(s,key) or nil
    if entry then return entry.label end
    for _,candidate in ipairs(dialFor(s)) do if candidate.key==key then return candidate.label end end
    return key or "No maneuver selected"
end
local function dialButton(id,text,x,y,color,width)
    return '<Button id="'..id..'" onClick="STA2E_UI" position="'..x..' '..y..' 0" width="'..(width or 205)..'" height="50" fontSize="18" color="'..(color or '#284A66')..'">'..xml(text)..'</Button>'
end
local function publicVisibility(owner)
    local other=owner=="Blue" and "Red" or "Blue"
    return other.."|Black|Grey|White|Brown|Orange|Yellow|Green|Teal|Purple|Pink"
end
local function render(s)
    local dial=member(s,"dial")
    if dial then
        local state=s.state.status or "planning"
        local chosen=maneuverLabel(s,s.state.maneuver)
        local private={'<Panel visibility="'..s.owner..'" width="700" height="820" color="#102432F2">',
            '<Text text="'..xml(s.name)..'" position="0 375 0" width="680" height="35" fontSize="24"/>'}
        if state=="planning" then
            table.insert(private,'<Text text="PLAN MANEUVER" position="0 335 0" width="680" height="32" fontSize="18"/>')
            table.insert(private,'<Text text="'..xml(chosen)..'" position="0 300 0" width="680" height="32" fontSize="20" color="#FFD86B"/>')
            local slots={}
            -- Six fixed columns: hard left, bank left, straight,
            -- bank right, hard right, Come About. Blank if unavailable.
            local columns={TL=-275,BL=-165,SL=-165,S=-55,BR=55,SR=55,TR=165,CA=275}
            local maxSpeed=5
            for _,entry in ipairs(dialFor(s)) do
                local speed=tonumber(entry.key:match("%d+$"))
                if speed and speed>maxSpeed and speed<=6 then maxSpeed=speed end
            end
            for speed=1,maxSpeed do
                for prefix,x in pairs(columns) do
                    slots[prefix..speed]={x,225-(maxSpeed-speed)*57}
                end
            end
            slots.R1={-55,225-maxSpeed*57};slots.R2={-55,168-maxSpeed*57};slots.R3={-55,111-maxSpeed*57}
            for _,move in ipairs(dialFor(s)) do
                local slot=slots[move.key]
                if slot then
                    local shade=({green="#256348",white="#526777",red="#863B3B"})[move.difficulty]
                    if move.key==s.state.maneuver then shade="#C69A2B" end
                    table.insert(private,dialButton("select_"..move.key,move.label,slot[1],slot[2],shade,100))
                end
            end
            table.insert(private,dialButton("lock","LOCK MANEUVER",0,85-maxSpeed*57,"#256348",430))
        elseif state=="locked" then
            table.insert(private,'<Text text="MANEUVER LOCKED" position="0 330 0" width="680" height="32" fontSize="18"/>')
            table.insert(private,'<Text text="'..xml(chosen)..'" position="0 280 0" width="680" height="45" fontSize="28" color="#FFD86B"/>')
            if STA2E.game.phase=="planning" then table.insert(private,dialButton("change","CHANGE MANEUVER",0,205,"#526777",430))
            else table.insert(private,dialButton("reveal","REVEAL MANEUVER",0,205,"#9A792B",430)) end
        elseif state=="revealed" then
            table.insert(private,'<Text text="REVEALED: '..xml(chosen)..'" position="0 315 0" width="680" height="45" fontSize="27" color="#FFD86B"/>')
            table.insert(private,dialButton("move","EXECUTE",-115,225,"#256348",205))
            table.insert(private,dialButton("modify_toggle","MODIFY MANEUVER",115,225,"#9A792B",205))
        elseif state=="action" then
            table.insert(private,'<Text text="'..xml(chosen)..' EXECUTED" position="0 330 0" width="680" height="38" fontSize="23"/>')
            table.insert(private,'<Text text="PERFORM ACTION" position="0 285 0" width="680" height="35" fontSize="20" color="#FFD86B"/>')
            for i,key in ipairs((s.capabilities and s.capabilities.actions) or {}) do table.insert(private,dialButton("action_"..key,key,((i-1)%2==0 and -115 or 115),210-math.floor((i-1)/2)*62,"#284A66")) end
            table.insert(private,dialButton("undo","UNDO MOVEMENT",-115,55,"#526777"))
            table.insert(private,dialButton("finish","SKIP / FINISH",115,55,"#863B3B"))
        else
            table.insert(private,'<Text text="ACTIVATION COMPLETE" position="0 320 0" width="680" height="40" fontSize="24"/>')
            table.insert(private,'<Text text="'..xml(chosen)..'" position="0 270 0" width="680" height="35" fontSize="20"/>')
        end
        table.insert(private,dialButton("tool_home","SHIP TOOLS",0,-350,"#375A78",300))
        table.insert(private,'</Panel>')
        local publicState=(state=="planning" and "PLANNING") or (state=="locked" and "MANEUVER ASSIGNED") or (state=="revealed" and ("REVEALED: "..chosen)) or (state=="action" and (chosen.." EXECUTED · ACTION")) or (chosen.." · COMPLETE")
        table.insert(private,'<Panel visibility="'..publicVisibility(s.owner)..'" width="620" height="180" color="#102432F2"><Text text="'..xml(s.name)..'" position="0 45 0" width="600" height="35" fontSize="24"/><Text text="'..xml(publicState)..'" position="0 -10 0" width="600" height="40" fontSize="21"/></Panel>')
        -- Object XML uses canvas coordinates, not physical-button coordinates.
        -- Keep the canvas plane unrotated; lift in canvas Z, not world Y.
        local markup=table.concat(private):gsub('<Text ', '<Text color="#FFFFFF" ')
        -- Highlighted labels already specify a color; avoid duplicate XML attributes.
        markup=markup:gsub('<Text color="#FFFFFF" ([^>]-) color="([^"]+)"', '<Text %1 color="%2"')
        markup=markup:gsub('<Button ', '<Button textColor="#FFFFFF" ')
        local root='<Panel id="sta2e_dashboard" width="700" height="820" position="0 0 -120" rotation="0 0 180" scale="0.4 0.4 1" color="#00000000" raycastTarget="false">'
        dial.UI.setXml(s.state.dialOpen==true and (root..markup..'</Panel>') or "")
