    end,15)
    return "Deploying missing components."
end
local function maneuver(s,key)
    for _,entry in ipairs(dialFor(s)) do if entry.key==key then return entry end end
    return nil
end
local ACTION_BAGS={EVA="f087d1",SCN="b36f7f",BS="655fff",TL="1649f4",CLK="8d45a9",REG="0afb47",AUX="2d55f5",SHIELD="df60bd",TIME="7eed80",DISABLED="bd57e7",CRIT="aae8f1",DRONE="f551e4",MISSION="c454b4",REINFORCE="80a381",LATINUM="345737"}
local function spawnActionToken(s,key)
    if key=="ECHO" then tell(s.owner,"Sensor Echo recorded. Move the base manually with the normal template so card effects remain flexible.");return end
    local bag=obj(ACTION_BAGS[key]);local base=member(s,"base")
    if not bag or not base then tell(s.owner,"Action recorded; its table token bag is unavailable.");return end
    local p,r=base.getPosition(),base.getRotation();local side=math.rad(r.y+90)
    local count=(s.state.spawnedTokens or 0)+1;s.state.spawnedTokens=count
    local ahead=math.rad(r.y);local lane=(count-1)%5-2;local gap=1.8+math.floor((count-1)/5)*0.6
    local target={p.x-math.sin(side)*gap-math.sin(ahead)*lane*0.42,p.y+1,p.z-math.cos(side)*gap-math.cos(ahead)*lane*0.42}
    bag.takeObject({position=target,callback_function=function(token) if token then token.setGMNotes("STA2E_SHIP_TOKEN|"..s.instanceId.."|"..key);if key=="TL" then token.setName(s.name) end end end})
end
function STA2E_Command(params)
    local s=shipFor(params.object)
    if not s or s.owner~=params.color then tell(params.color,"Only the owning player may control this ship.");return end
    local cmd=params.command or ""
    if cmd=="deploy" then tell(params.color,deploy(s));return end
    if cmd=="open_dial" then
        local dial=member(s,"dial")
        if not dial then tell(params.color,"Deploy / Repair the ship first.");return end
        s.state.dialOpen=not (s.state.dialOpen==true)
        if s.state.dialOpen then
            local p=params.object.getPosition()
            local target={x=p.x-4.2,y=p.y+0.3,z=p.z}
            dial.setPosition(target)
        end
        refresh(s);return
    end
    if cmd=="sync" then sync(s);return end
    if not complete(s) then tell(params.color,"Deploy / Repair this ship first.");return end
    local phase=STA2E.game.phase
    if cmd:sub(1,7)=="select_" then
        local key=cmd:sub(8)
        if not maneuver(s,key) then tell(params.color,"That maneuver is not on this ship's dial.");return end
        if phase~="planning" then tell(params.color,"Open play: selecting a maneuver outside Planning.") end
        if s.state.status=="locked" then tell(params.color,"Choose Change Maneuver before selecting a different maneuver.");return end
        s.state.maneuver=key;s.state.status="planning"
    elseif cmd=="lock" then
        if phase~="planning" then tell(params.color,"Maneuvers may only be locked during Planning.");return end
        if not s.state.maneuver then tell(params.color,"Choose a maneuver before locking it.");return end
        s.state.status="locked"
        broadcastToAll(s.name.." has locked in its maneuver.",{0.82,0.90,1})
    elseif cmd=="change" then
        if phase~="planning" or s.state.status~="locked" then tell(params.color,"That maneuver can no longer be changed.");return end
        s.state.status="planning"
    elseif cmd=="reveal" then
        if not s.state.maneuver then tell(params.color,"Choose a maneuver before revealing it.");return end
        if phase~="activation" or s.state.status~="locked" then tell(params.color,"Open play: revealing outside the normal Activation sequence.") end
        s.state.status="revealed"
        broadcastToAll(s.name.." has revealed a maneuver of "..maneuverLabel(s,s.state.maneuver)..".",{0.82,0.90,1})
    elseif cmd=="move" then
        local move=MOVE_DEFS[s.state.maneuver]
        if not move or not maneuver(s,s.state.maneuver) then tell(params.color,"No supported movement for this selection.");return end
        if phase~="activation" or s.state.status~="revealed" then tell(params.color,"Open play: executing outside the normal revealed Activation step.") end
        local base=member(s,"base");local p,r=base.getPosition(),base.getRotation()
        s.undo={position={p.x,p.y,p.z},rotation={r.x,r.y,r.z},state=copy(s.state),round=STA2E.game.round}
        local angle=math.rad(r.y);local side=math.rad(r.y+90)
        base.setPosition({p.x-math.sin(angle)*(move.forward or 0)+math.sin(side)*(move.side or 0),p.y,p.z-math.cos(angle)*(move.forward or 0)+math.cos(side)*(move.side or 0)})
        base.setRotation({r.x,r.y+(move.rotate or 0),r.z})
        s.state.status="action";sync(s)
        broadcastToAll(s.name.." has executed a maneuver of "..maneuverLabel(s,s.state.maneuver)..".",{0.82,0.90,1})
    elseif cmd=="undo" then
        if not s.undo or s.undo.round~=STA2E.game.round then tell(params.color,"No movement undo is available this round.");return end
        local base=member(s,"base");base.setPosition(s.undo.position);base.setRotation(s.undo.rotation)
        s.state=s.undo.state;s.undo=nil;sync(s)
    elseif cmd:sub(1,7)=="action_" then
        local key=cmd:sub(8)
        local allowed=false;for _,action in ipairs((s.capabilities and s.capabilities.actions) or {}) do if action==key then allowed=true end end
        if not allowed then tell(params.color,"Open play: recording a card-granted action.") end
        if phase~="activation" or s.state.status~="action" then tell(params.color,"Open play: recording an action outside the normal action step.") end
        s.state.action=key;spawnActionToken(s,key)
        if s.state.status=="action" then s.state.status="complete" end
    elseif cmd=="finish" then
        if phase~="activation" or s.state.status~="action" then tell(params.color,"Open play: marking this ship complete outside the normal action step.") end
        s.state.status="complete"
    else tell(params.color,"Unknown ship command.");return end
    refresh(s)
    hud()
end
local phaseConfirm={}
local function lockedCount()
    local locked,total=0,0
    for _,s in pairs(STA2E.ships) do
        if obj(s.cardGUID) then total=total+1;if s.state and s.state.status=="locked" then locked=locked+1 end end
    end
    return locked,total
end
function hud()
    if STA2E.loading or STA2E.reconciling then return end
    local locked,total=lockedCount()
    local progress=STA2E.game.phase=="planning" and (" · "..locked.."/"..total.." LOCKED") or ""
    local bar='<Panel rectAlignment="UpperLeft" offsetXY="58 -62" width="455" height="72" color="#102432EE">'..
        '<Text text="ROUND '..STA2E.game.round..' · '..string.upper(xml(STA2E.game.phase))..progress..'" position="-5 18 0" width="430" height="28" fontSize="18"/>'..
        '<Button id="advance" onClick="STA2E_PhaseUI" position="-108 -17 0" width="205" height="30" fontSize="15">ADVANCE PHASE</Button>'..
        '<Button id="import" onClick="STA2E_ImportUI" position="108 -17 0" width="205" height="30" fontSize="15">FLEET SETUP</Button></Panel>'
    UI.setXml(bar..fleetPanel())
end
function STA2E_PhaseUI(player)
    if not player or not own(player.color) then tell(player and player.color or "Black","Only a seated Red or Blue player may advance the phase.");return end
    local g=STA2E.game
    if g.phase=="planning" then
        local locked,total=lockedCount()
        if locked<total then
            local now=Time.time
            if not phaseConfirm[player.color] or now-phaseConfirm[player.color]>5 then
                phaseConfirm[player.color]=now
                tell(player.color,tostring(total-locked).." ship(s) do not have locked maneuvers. Click Advance Phase again within 5 seconds to continue anyway.")
                return
            end
        end
    end
    phaseConfirm={}
    if next(STA2E.pending) or next(STA2E.imports) then tell(player.color,"Wait for spawning to finish.");return end
    if g.phase=="planning" then
        g.phase="activation"
    elseif g.phase=="activation" then
        g.phase="combat"
    elseif g.phase=="combat" then g.phase="end"
    else
        g.phase="planning";g.round=g.round+1
        for _,s in pairs(STA2E.ships) do
            local dialOpen=s.state and s.state.dialOpen==true
            s.state={status="planning",dialOpen=dialOpen};s.undo=nil;refresh(s)
        end
    end
    for _,s in pairs(STA2E.ships) do refresh(s) end
    hud()
end
function STA2E_PhaseFromDial(params)
    local player=Player[params.color]
    if not player or not own(params.color) then tell(params.color,"Only a seated Red or Blue player may advance the phase.");return end
    STA2E_PhaseUI(player)
end
-- STA2E fleet paste/import milestone.
-- CATALOG is populated from the compact generated catalog during onLoad.

local function array(value)
    if type(value)~="table" then return false end
    local n=0
    for k in pairs(value) do
        if type(k)~="number" or k<1 or k%1~=0 then return false end
        n=n+1
    end
    return n==#value
end

local function join(values)
    local result={}
    for _,value in ipairs(values or {}) do table.insert(result,tostring(value)) end
    return table.concat(result,", ")
end

local function cardData(card)
    if not card or not card.cardImage or not card.cardBack then return nil end
    if card.objectKind=="tile" then
        return {
            Name="Custom_Tile",
            Transform={posX=0,posY=1.2,posZ=0,rotX=0,rotY=180,rotZ=0,
                scaleX=(card.objectScale and card.objectScale.x) or 1,
                scaleY=(card.objectScale and card.objectScale.y) or 1,
                scaleZ=(card.objectScale and card.objectScale.z) or 1},
            Nickname=card.name or card.id,Description=card.id,GMNotes="",
            ColorDiffuse={r=1,g=1,b=1},LayoutGroupSortIndex=0,Value=card.cost or 0,
            Locked=false,Grid=true,Snap=true,IgnoreFoW=false,MeasureMovement=false,
            DragSelectable=true,Autoraise=true,Sticky=true,Tooltip=true,GridProjection=false,
            HideWhenFaceDown=false,Hands=false,
            CustomImage={ImageURL=card.cardImage,ImageSecondaryURL=card.cardBack,ImageScalar=1,WidthScale=0,
                CustomTile={Type=3,Thickness=0.1,Stackable=false,Stretch=true}},
            LuaScript="",LuaScriptState="",XmlUI=""
        }
    end
    local ordinal=CATALOG_ORDINAL[card.id] or 1
    local deckKey=10000+ordinal
    local cardId=deckKey*100
    local width,height=1,1
    if card.sheet then
        cardId=card.sheet.ttsCardId
        deckKey=math.floor(cardId/100)
        width=card.sheet.width
        height=card.sheet.height
    end
    local customDeck={}
    customDeck[tostring(deckKey)]={
        FaceURL=card.cardImage,BackURL=card.cardBack,
        NumWidth=width,NumHeight=height,BackIsHidden=true,UniqueBack=card.sheet and card.sheet.uniqueBack==true or false,Type=0
    }
    return {
        Name="CardCustom",
        Transform={posX=0,posY=1.2,posZ=0,rotX=0,rotY=180,rotZ=0,scaleX=1,scaleY=1,scaleZ=1},
        Nickname=card.name or card.id,Description=card.id,GMNotes="",
        AltLookAngle={x=0,y=0,z=0},ColorDiffuse={r=0.713235259,g=0.713235259,b=0.713235259},
        LayoutGroupSortIndex=0,Value=card.cost or 0,Locked=false,Grid=true,Snap=true,
        IgnoreFoW=false,MeasureMovement=false,DragSelectable=true,Autoraise=true,Sticky=true,
        Tooltip=true,GridProjection=false,HideWhenFaceDown=true,Hands=true,CardID=cardId,
        SidewaysCard=false,CustomDeck=customDeck,LuaScript="",LuaScriptState="",XmlUI=""
    }
end

local function canonicalFromDevelopment(value)
    if not value or value.schemaVersion~=1 or not array(value.ships) then return nil,"Unsupported JSON fleet format." end
    local fleet={schemaVersion=2,fleetId=value.fleetId,source={kind="development-json"},ships={},resources={},warnings={}}
    for _,sourceShip in ipairs(value.ships) do
        local ship={shipCardId=sourceShip.shipCardId,cards={}}
        if sourceShip.captainId then table.insert(ship.cards,{cardId=sourceShip.captainId,role="captain"}) end
        for _,id in ipairs(sourceShip.upgradeIds or {}) do table.insert(ship.cards,{cardId=id,role=(CATALOG[id] and CATALOG[id].type) or "upgrade"}) end
        table.insert(fleet.ships,ship)
    end
    return fleet
end

local function parseFleet(text)
    text=tostring(text or ""):gsub("^\239\187\191","")
    if text:match("^%s*{") then
        local value=decode(text)
        if value and value.schemaVersion==2 and array(value.ships) then return value end
        return canonicalFromDevelopment(value)
    end
    local fleet={schemaVersion=2,source={kind="utopia-tts"},ships={},resources={},warnings={}}
    local unknown,missing,ungrouped={},{},{}
    local current=nil
    for raw in (text.."\n"):gmatch("([^\r\n]*)[\r\n]") do
        local id=raw:match("^%s*(.-)%s*$")
        if id:match("^%-%-%-+%s*$") or id:lower():match("^generated by utopia") then break end
        if id~="" then
            local hidden=id:sub(1,1)=="#"
            if hidden then id=id:sub(2):match("^%s*(.-)%s*$") end
            local card=CATALOG[id]
            if not card then
                table.insert(unknown,id)
            elseif not card.cardImage or not card.cardBack then
                table.insert(missing,id)
            elseif card.type=="ship" then
                current={shipCardId=id,cards={}}
                table.insert(fleet.ships,current)
            elseif card.type=="resource" then
                table.insert(fleet.resources,{cardId=id,role="resource",hidden=hidden or nil})
            elseif current then
                table.insert(current.cards,{cardId=id,role=card.type or "upgrade",hidden=hidden or nil})
            else
                table.insert(ungrouped,id)
            end
        end
    end
    if #unknown>0 then return nil,"Unknown ID(s): "..join(unknown) end
    if #missing>0 then return nil,"No full-card asset for: "..join(missing) end
    if #ungrouped>0 then return nil,"Card(s) before the first ship: "..join(ungrouped) end
    if #fleet.ships==0 then return nil,"Paste a list containing at least one ship ID." end
    return fleet
end

local function fleetLayout(fleet)
    local maxSlots,maxRows=14,3
    local rows={}
    local function place(entries,shipIndex,standalone)
        local length=#entries
        if length>maxSlots then
            local label=standalone and "The resource group" or ("Ship "..tostring(shipIndex))
            return false,label.." has "..length.." cards; the play mat allows 14 per row."
        end
        local row=rows[#rows]
        local needed=length
        if row and row.used>0 then needed=needed+2 end
        if not row or row.used+needed>maxSlots then
            if #rows>=maxRows then return false,"Fleet needs more than 3 rows of 14 card spaces." end
            row={used=0,groups={}}
            table.insert(rows,row)
        end
        local start=row.used==0 and 1 or row.used+3
        table.insert(row.groups,{entries=entries,shipIndex=shipIndex,standalone=standalone,start=start})
        row.used=start+length-1
        return true
    end
    for i,ship in ipairs(fleet.ships or {}) do
        local entries={{cardId=ship.shipCardId,role="ship"}}
        for _,entry in ipairs(ship.cards or {}) do table.insert(entries,entry) end
        local ok,err=place(entries,i,false)
        if not ok then return nil,err end
    end
    if #(fleet.resources or {})>0 then
        local ok,err=place(fleet.resources,nil,true)
        if not ok then return nil,err end
    end
    return rows
end

local function reviewFleet(fleet)
    if not fleet or fleet.schemaVersion~=2 or not array(fleet.ships) or #fleet.ships==0 then return nil,"No valid ships were found." end
    local total,cost,ready=0,0,0
    local names={}
    for _,ship in ipairs(fleet.ships) do
        local root=CATALOG[ship.shipCardId]
        if not root or root.type~="ship" then return nil,"Unknown ship ID: "..tostring(ship.shipCardId) end
        if not root.cardImage or not root.cardBack then return nil,"No full-card asset for: "..ship.shipCardId end
        total=total+1
        cost=cost+(tonumber(root.cost) or 0)
        if SHIP_DEFINITIONS[ship.shipCardId] then ready=ready+1 end
        table.insert(names,(root.name or root.id).." ["..tostring(root.cost or "?").."]")
        if not array(ship.cards or {}) then return nil,"Invalid card list for "..root.id end
        for _,entry in ipairs(ship.cards or {}) do
            local card=CATALOG[entry.cardId]
            if not card then return nil,"Unknown ID: "..tostring(entry.cardId) end
            if not card.cardImage or not card.cardBack then return nil,"No full-card asset for: "..entry.cardId end
            total=total+1
            cost=cost+(tonumber(card.cost) or 0)
        end
    end
    for _,entry in ipairs(fleet.resources or {}) do
        local card=CATALOG[entry.cardId]
        if not card or not card.cardImage or not card.cardBack then return nil,"Resource cannot be spawned: "..tostring(entry.cardId) end
        total=total+1;cost=cost+(tonumber(card.cost) or 0)
    end
    local layout,layoutError=fleetLayout(fleet)
    if not layout then return nil,layoutError end
    return {ships=#fleet.ships,cards=total,cost=cost,ready=ready,names=names,rows=#layout}
end

function fleetPanel()
    local color=STA2E.fleetColor
    if not color then return "" end
    local buffer=STA2E.fleetText[color] or ""
    local status=STA2E.fleetStatus[color] or "Paste Utopia TTS card IDs, then preview the fleet."
    return '<Panel id="fleetPanel" visibility="'..color..'" rectAlignment="MiddleCenter" width="720" height="620" color="#102432F5">'..
        '<Text text="FLEET SETUP" position="0 275 0" width="680" height="42" fontSize="28" color="#FFFFFF"/>'..
        '<Text text="Paste one card ID per line. Each ship begins a new group." position="0 235 0" width="660" height="30" fontSize="17" color="#C8D9E8"/>'..
        '<InputField id="fleetInput" onValueChanged="STA2E_FleetText" onEndEdit="STA2E_FleetText" text="'..xml(buffer):gsub("\r",""):gsub("\n","&#10;")..'" position="0 55 0" width="650" height="320" fontSize="20" lineType="MultiLineNewline" color="#18354D" textColor="#FFFFFF"/>'..
        '<Text text="'..xml(status)..'" position="0 -145 0" width="650" height="90" fontSize="17" color="#FFFFFF"/>'..
        '<Button id="previewFleet" onClick="STA2E_FleetPreview" position="-170 -245 0" width="190" height="48" fontSize="18" color="#375A78" textColor="#FFFFFF">PREVIEW</Button>'..
        '<Button id="spawnFleet" onClick="STA2E_FleetSpawn" position="45 -245 0" width="220" height="48" fontSize="18" color="#26704A" textColor="#FFFFFF">SPAWN CARDS</Button>'..
        '<Button id="closeFleet" onClick="STA2E_FleetClose" position="245 -245 0" width="150" height="48" fontSize="18" color="#733E43" textColor="#FFFFFF">CLOSE</Button>'..
        '</Panel>'
end

function STA2E_FleetText(player,value,id)
    if player and own(player.color) then STA2E.fleetText[player.color]=value or "" end
end

function STA2E_FleetPreview(player)
    if not player or not own(player.color) then return end
    local fleet,err=parseFleet(STA2E.fleetText[player.color])
    local review
    if fleet then review,err=reviewFleet(fleet) end
    if not review then
        STA2E.fleetStatus[player.color]="Cannot spawn: "..tostring(err)
    else
        local physical=review.ready==review.ships and "All ship definitions are ready." or (review.ready.." of "..review.ships.." ship definitions can deploy; all cards can spawn.")
        STA2E.fleetStatus[player.color]=review.ships.." ship(s), "..review.cards.." card(s), "..review.cost.." SP · "..review.rows.." of 3 rows.\n"..table.concat(review.names,"; ").."\n"..physical
        STA2E.fleetPlans[player.color]=fleet
    end
    hud()
end

function STA2E_FleetClose(player)
    if player and STA2E.fleetColor==player.color then STA2E.fleetColor=nil;hud() end
end

local function validate(fleet)
    local _,err=reviewFleet(fleet)
    return err
end

function STA2E_ImportFleet(params)
    local color=params.color
    if not own(color) then return {ok=false,error="Sit in Blue or Red to import."} end
    if next(STA2E.imports) then return {ok=false,error="Wait for the current fleet import to finish."} end
    local fleet=params.fleet or decode(params.json)
    local err=validate(fleet)
    if err then return {ok=false,error=err} end
    fleet.fleetId=fleet.fleetId or ("paste-"..tostring(STA2E.game.nextId+1))
    local key=color..":"..fleet.fleetId
    if STA2E.game.fleets[key] or STA2E.imports[key] then return {ok=false,error="This fleet is already imported. Change its fleetId to import another copy."} end
    local sign=color=="Blue" and 1 or -1
    local jobs,ids={},{}
    local layout,layoutError=fleetLayout(fleet)
    if not layout then return {ok=false,error=layoutError} end
    local shipInstances={}
    for i,ship in ipairs(fleet.ships) do
        local instanceId=nextId()
        table.insert(ids,instanceId)
        local root=CATALOG[ship.shipCardId]
        local deployX=(i-(#fleet.ships+1)/2)*7
        shipInstances[i]={schemaVersion=1,role="card",instanceId=instanceId,definitionId=root.id,name=root.name,owner=color,fleetId=key,refs={},upgrades={},capabilities=capabilities(root.id),state={status="planning",dialOpen=false},spawnPosition={x=deployX,y=1.3,z=sign*10},physicalReady=SHIP_DEFINITIONS[root.id]~=nil}
    end
    local spacing=2.7
    local cardEdge,rowSpacing=32,5
    local rowDirection=color=="Blue" and -1 or 1
    local cardRotation=color=="Blue" and 0 or 180
    for rowIndex,row in ipairs(layout) do
        local left=-((row.used-1)*spacing)/2
        local z=sign*(cardEdge-(rowIndex-1)*rowSpacing)
        for _,group in ipairs(row.groups) do
            local s=group.shipIndex and shipInstances[group.shipIndex] or nil
            local anchorSlot=group.start
            local hiddenOffset=0
            for j,entry in ipairs(group.entries) do
                local slot=group.start+j-1
                if entry.hidden then hiddenOffset=hiddenOffset+1 else anchorSlot=slot;hiddenOffset=0 end
                local x=rowDirection*(left+((entry.hidden and anchorSlot or slot)-1)*spacing+(entry.hidden and hiddenOffset*0.42 or 0))
                local cardZ=z+(entry.hidden and sign*hiddenOffset*0.18 or 0)
                table.insert(jobs,{ship=s,cardId=entry.cardId,root=not group.standalone and j==1,hidden=entry.hidden==true,position={x,entry.hidden and 1.24 or 1.2,cardZ},index=j-1,standalone=group.standalone})
            end
        end
    end
    local tx={objects={},roots={},left=#jobs,ids=ids};STA2E.imports[key]=tx
    local function rollback(reason)
        if STA2E.imports[key]~=tx then return end
        STA2E.imports[key]=nil
        for _,id in ipairs(ids) do STA2E.ships[id]=nil end
        for _,object in ipairs(tx.objects) do if obj(object.getGUID()) then object.destruct() end end
        tell(color,"Import rolled back: "..reason)
    end
    local function finish()
        if tx.left~=0 then return end
        for _,s in pairs(tx.roots) do
            for _,u in ipairs(s.upgrades) do
                local object=obj(u.guid)
                if object then object.call("STA2E_SetMemory",{schemaVersion=1,role="upgrade",instanceId=s.instanceId,cardGUID=s.cardGUID,cardId=u.cardId,fleetId=key}) end
            end
            table.sort(s.upgrades,function(a,b)return a.index<b.index end)
            STA2E.ships[s.instanceId]=s;refresh(s)
        end
        STA2E.game.fleets[key]=ids
        STA2E.imports[key]=nil
        tell(color,"Fleet cards spawned.")
    end
    for _,jobValue in ipairs(jobs) do
        local job=jobValue
        local card=CATALOG[job.cardId]
        local data=cardData(card)
        if not data then rollback("No complete card asset for "..job.cardId);break end
        data.GUID=nil;data.States=nil;data.LuaScript=MEMBER_SCRIPT;data.XmlUI=""
        if job.root then data.Transform.scaleX=1.2;data.Transform.scaleZ=1.2 end
        data.LuaScriptState=JSON.encode({schemaVersion=1,role="pending",transaction=key})
        local ok,spawnError=pcall(function()
            spawnObjectData({data=data,position=job.position,rotation={0,cardRotation,0},callback_function=function(object)
                if STA2E.imports[key]~=tx then object.destruct();return end
                if job.hidden then object.flip() end
                table.insert(tx.objects,object)
                if job.standalone then
                    object.call("STA2E_SetMemory",{schemaVersion=1,role="fleetCard",fleetId=key,cardId=job.cardId})
                else
                    local s=job.ship
                    if job.root then s.cardGUID=object.getGUID();tx.roots[s.instanceId]=s
                    else table.insert(s.upgrades,{cardId=job.cardId,guid=object.getGUID(),index=job.index}) end
                end
                tx.left=tx.left-1;finish()
            end})
        end)
        if not ok then rollback(tostring(spawnError));break end
    end
    Wait.time(function() rollback("some cards did not finish spawning") end,15)
    return {ok=true,pending=true}
end

function STA2E_FleetSpawn(player)
    if not player or not own(player.color) then return end
    local fleet,err=parseFleet(STA2E.fleetText[player.color])
    if fleet then local ignored;ignored,err=reviewFleet(fleet) end
    if not fleet or err then STA2E.fleetStatus[player.color]="Cannot spawn: "..tostring(err);hud();return end
    local result=STA2E_ImportFleet({color=player.color,fleet=fleet})
    if not result.ok then STA2E.fleetStatus[player.color]="Cannot spawn: "..result.error;hud();return end
    STA2E.fleetColor=nil;hud()
end

function STA2E_ImportUI(player)
    if not player or not own(player.color) then tell(player and player.color or "Black","Sit in Blue or Red to set up a fleet.");return end
    STA2E.fleetColor=player.color
    STA2E.fleetText[player.color]=STA2E.fleetText[player.color] or ""
    STA2E.fleetStatus[player.color]="Paste Utopia TTS card IDs, then preview the fleet."
    hud()
end
-- Round UX 0.26. This module is appended after the existing controller and importer.
-- It uses their ship association and render functions without changing object XML placement.
STA2E.pendingMoves = {}
STA2E.manageCard = {}
STA2E.modifyShip = {}
-- Provisional bank 3/4 calibration. Preserve the confirmed bank 1 and the
-- bank 2 offsets while testing a longer, slightly more lateral endpoint.
-- Both hands use the same values, mirrored by the sign of side/rotation.
local BANK_CALIBRATION={
    [3]={forward=6.40,side=2.62},
    [4]={forward=7.65,side=3.13},
}
for speed,calibration in pairs(BANK_CALIBRATION) do
    for _,hand in ipairs({{key="BL",sign=1},{key="BR",sign=-1}}) do
        local move=MOVE_DEFS[hand.key..speed]
        if move then move.forward=calibration.forward;move.side=hand.sign*calibration.side end
    end
end
-- The physical base artwork's left/right orientation is opposite the
-- movement table's local side convention. Mirror bank and turn paths together
-- so their lateral travel and final facing match the printed L/R labels.
for _,prefix in ipairs({"BL","BR","TL","TR"}) do
    for speed=1,4 do
        local move=MOVE_DEFS[prefix..speed]
        if move then move.side=-(move.side or 0);move.rotate=-(move.rotate or 0) end
    end
end
for speed=1,4 do
    local comeAbout=MOVE_DEFS["CA"..speed]
    if comeAbout then comeAbout.finishRotateOnly=true end
end

local function captainFor(s)
    for _,entry in ipairs(s.upgrades or {}) do
        local card=CATALOG[entry.cardId]
        if card and card.type=="captain" then return card end
    end
    return nil
end

local function skillFor(s)
    local captain=captainFor(s)
    return tonumber(s.skillOverride) or (captain and tonumber(captain.skill)) or 0
end

local function sidebar()
    local ships={}
    for _,s in pairs(STA2E.ships) do
        if obj(s.cardGUID) then table.insert(ships,s) end
    end
    local phase=STA2E.game.phase
    table.sort(ships,function(a,b)
        local x,y=skillFor(a),skillFor(b)
        if x~=y then return phase=="combat" and x>y or (phase~="combat" and x<y) end
        local initiative=STA2E.game.initiative or "Blue"
        if a.owner~=b.owner then return a.owner==initiative end
        return a.instanceId<b.instanceId
    end)
    local parts={'<Panel id="shipSidebar" rectAlignment="UpperLeft" offsetXY="58 -150" width="380" height="'..(95+math.max(#ships,1)*46)..'" color="#102432ED">',
        '<Text text="'..xml(string.upper(phase))..' · SHIPS" position="-55 '..(18+math.max(#ships,1)*23)..' 0" width="240" height="33" fontSize="20" color="#FFFFFF"/>',
        '<Button id="initiative_toggle" onClick="STA2E_SidebarClick" position="123 '..(18+math.max(#ships,1)*23)..' 0" width="120" height="27" fontSize="12">INIT '..xml(STA2E.game.initiative or "Blue")..'</Button>',
        '<Text text="Skill | Captain | Ship · Color" position="0 '..(-13+math.max(#ships,1)*23)..' 0" width="355" height="24" fontSize="14" color="#C8D9E8"/>'}
    for i,s in ipairs(ships) do
        local captain=captainFor(s)
        local name=captain and captain.name or "No captain"
        local status=s.state or {}
        local marker=(status.maneuver and "M" or "-").."/"..((status.status=="complete" or status.status=="action") and "A" or "-").."/"..(status.fired and "F" or "-")
        local shade=s.owner=="Red" and "#713839" or "#285779"
        if phase=="combat" and status.fired then shade="#48515D" end
        local y=math.max(#ships,1)*23-42-(i-1)*46
        table.insert(parts,'<Button id="focus_'..xml(s.instanceId)..'" onClick="STA2E_SidebarClick" position="-40 '..y..' 0" width="265" height="38" fontSize="14" color="'..shade..'" textColor="#FFFFFF">'..xml(tostring(skillFor(s))..' | '..name..' | '..s.name..' ['..marker..']')..'</Button>')
        table.insert(parts,'<Button id="skill_down_'..xml(s.instanceId)..'" onClick="STA2E_SidebarClick" position="106 '..y..' 0" width="27" height="38" fontSize="17">-</Button>')
        table.insert(parts,'<Button id="skill_up_'..xml(s.instanceId)..'" onClick="STA2E_SidebarClick" position="136 '..y..' 0" width="27" height="38" fontSize="17">+</Button>')
        table.insert(parts,'<Button id="fire_'..xml(s.instanceId)..'" onClick="STA2E_SidebarClick" position="166 '..y..' 0" width="27" height="38" fontSize="14">F</Button>')
    end
    if #ships==0 then table.insert(parts,'<Text text="Deploy a ship to list it here" position="0 -26 0" width="350" height="26" fontSize="15" color="#FFFFFF"/>') end
    table.insert(parts,'</Panel>')
    return table.concat(parts)
end

function STA2E_SidebarClick(player,value,id)
    if id=="initiative_toggle" and player and own(player.color) then
        STA2E.game.initiative=(STA2E.game.initiative or "Blue")=="Blue" and "Red" or "Blue"
        hud();return
    end
    local action,actionId=id and id:match('^(skill_down)_(.+)$')
    if not action then action,actionId=id and id:match('^(skill_up)_(.+)$') end
    if not action then action,actionId=id and id:match('^(fire)_(.+)$') end
    if action then
        local controlled=STA2E.ships[actionId]
        if not controlled or player.color~=controlled.owner then return end
        if action=="fire" then controlled.state.fired=not controlled.state.fired
        else controlled.skillOverride=math.max(0,skillFor(controlled)+(action=="skill_up" and 1 or -1)) end
        refresh(controlled);return
    end
    local instance=id and id:match('^focus_(.+)$')
    local s=instance and STA2E.ships[instance]
    if not s then return end
    local target=member(s,"base") or obj(s.cardGUID)
    if not target then return end
    local p=target.getPosition()
    player.lookAt({position=p,pitch=55,distance=16})
    target.highlightOn(s.owner,2)
    local card=obj(s.cardGUID)
    if card and card~=target then card.highlightOn(s.owner,2) end
end

local function managedObject(color)
    local guid=STA2E.manageCard[color]
    local card=obj(guid)
    local memory=metadata(card)
    if card and memory and (memory.role=="upgrade" or memory.role=="fleetCard") then return card,memory end
    STA2E.manageCard[color]=nil
    return nil,nil
end

local function managePanel()
    local parts={}
    for _,color in ipairs({"Blue","Red"}) do
        local card=managedObject(color)
        if card then
            table.insert(parts,'<Panel id="manage'..color..'" visibility="'..color..'" rectAlignment="MiddleRight" offsetXY="-20 0" width="330" height="285" color="#102432F5">'..
                '<Text text="MANAGE: '..xml(card.getName())..'" position="0 112 0" width="305" height="28" fontSize="18" color="#FFFFFF"/>'..
                '<Text text="Players decide card-effect legality" position="0 82 0" width="305" height="22" fontSize="13" color="#C8D9E8"/>'..
                '<Button id="time_add" onClick="STA2E_ManageAction" position="-82 42 0" width="145" height="34">+ TIME</Button>'..
                '<Button id="time_remove" onClick="STA2E_ManageAction" position="82 42 0" width="145" height="34">- TIME</Button>'..
                '<Button id="disable_add" onClick="STA2E_ManageAction" position="-82 1 0" width="145" height="34">+ DISABLE</Button>'..
                '<Button id="disable_remove" onClick="STA2E_ManageAction" position="82 1 0" width="145" height="34">- DISABLE</Button>'..
                '<Button id="discard" onClick="STA2E_ManageAction" position="-82 -52 0" width="145" height="34" color="#713839">DISCARD / FLIP</Button>'..
                '<Button id="close" onClick="STA2E_ManageAction" position="82 -52 0" width="145" height="34">CLOSE</Button></Panel>')
        end
    end
    return table.concat(parts)
end

local function modifyPanel()
    local parts={}
    local keys={}
    for key in pairs(MOVE_DEFS) do
        if key:match("^[A-Z]+%d+$") and key~="R180" then table.insert(keys,key) end
    end
    table.sort(keys)
    for _,color in ipairs({"Blue","Red"}) do
        local s=STA2E.ships[STA2E.modifyShip[color]]
        if s and s.owner==color and s.state.status=="revealed" then
            local rows=math.ceil(#keys/8)
            local height=150+rows*43
            local top=height/2-32
            table.insert(parts,'<Panel id="modify'..color..'" visibility="'..color..'" rectAlignment="MiddleCenter" width="760" height="'..height..'" color="#102432F8">')
            table.insert(parts,'<Text text="MODIFY MANEUVER · '..xml(s.name)..'" position="0 '..top..' 0" width="725" height="30" fontSize="20" color="#FFFFFF"/>')
            table.insert(parts,'<Text text="Choose any supported template; card effects decide legality" position="0 '..(top-30)..' 0" width="725" height="23" fontSize="13" color="#C8D9E8"/>')
            local firstY=top-65
            for i,key in ipairs(keys) do
                local column=(i-1)%8
                local row=math.floor((i-1)/8)
                local x=-315+column*90
                local y=firstY-row*43
                local shade=key==s.state.maneuver and '#256348' or '#285779'
                table.insert(parts,'<Button id="modify_'..key..'" onClick="STA2E_ModifyChoice" position="'..x..' '..y..' 0" width="82" height="35" fontSize="15" color="'..shade..'" textColor="#FFFFFF">'..key..'</Button>')
            end
            local foot=-height/2+30
            for _,button in ipairs({{'restore','RESTORE',-270},{'down','- SPEED',-90},{'up','+ SPEED',90},{'close','CLOSE',270}}) do
                table.insert(parts,'<Button id="modify_'..button[1]..'" onClick="STA2E_ModifyChoice" position="'..button[3]..' '..foot..' 0" width="165" height="36" fontSize="15">'..button[2]..'</Button>')
            end
            table.insert(parts,'</Panel>')
        else STA2E.modifyShip[color]=nil end
    end
    return table.concat(parts)
end

function STA2E_ManageCard(params)
    local card=params.object
    local m=metadata(card)
    if not own(params.color) or not m or (m.role~="upgrade" and m.role~="fleetCard") then return end
    local s=m.instanceId and STA2E.ships[m.instanceId]
    if s and s.owner~=params.color then tell(params.color,"Only the owning player can manage this card.");return end
    STA2E.manageCard[params.color]=card.getGUID()
    hud()
end

local TOKEN_BAGS={time="410976",disable="64e3ba"}
local function taggedTokens(card,kind)
    local prefix="STA2E_TOKEN|"..card.getGUID().."|"..kind
    local found={}
    for _,object in ipairs(getAllObjects()) do
        if object.getGMNotes() == prefix then table.insert(found,object) end
    end
    return found
end

local function clearCardTokens(card)
    local p=card.getPosition()
    local bounds=card.getBounds()
    local halfX=math.max(0.6,(bounds.size.x or 2)/2)
    local halfZ=math.max(0.6,(bounds.size.z or 3)/2)
    local removed={}
    for _,kind in ipairs({"time","disable"}) do
        for _,token in ipairs(taggedTokens(card,kind)) do removed[token.getGUID()]=token end
    end
    -- Also clear player-placed physical tokens sitting on the card.
    -- Cards are laid at 0 or 180 degrees in the fleet rows, so their AABB is usable here.
    for _,object in ipairs(getAllObjects()) do
        local kind=object.type
        if object~=card and (kind=="Custom_Token" or kind=="Chip" or kind=="Custom_Model") then
            local q=object.getPosition()
            if q.y>=p.y-0.1 and q.y<=p.y+2 and math.abs(q.x-p.x)<=halfX and math.abs(q.z-p.z)<=halfZ then
                removed[object.getGUID()]=object
            end
        end
    end
    for _,token in pairs(removed) do token.destruct() end
end

function STA2E_ManageAction(player,value,id)
    if not player or not own(player.color) then return end
    local card,m=managedObject(player.color)
    if not card then hud();return end
    if id=="close" then STA2E.manageCard[player.color]=nil;hud();return end
    if id=="discard" then
        clearCardTokens(card)
        STA2E.manageCard[player.color]=nil
        card.flip();hud();return
    end
    local kind,operation=id:match("^(time)_(%a+)$")
    if not kind then kind,operation=id:match("^(disable)_(%a+)$") end
    if operation~="add" and operation~="remove" then return end
    if not kind then return end
    local tokens=taggedTokens(card,kind)
    if operation=="remove" then
        if #tokens>0 then tokens[#tokens].destruct() else tell(player.color,"No managed "..kind.." token on this card.") end
        return
    end
    local bag=obj(TOKEN_BAGS[kind])
    if not bag then tell(player.color,"The "..kind.." token bag is missing.");return end
    local p=card.getPosition()
    local index=#tokens
    bag.takeObject({position={p.x-0.6+(index%4)*0.38,p.y+0.5,p.z+0.8+math.floor(index/4)*0.38},callback_function=function(token)
        if token then token.setGMNotes("STA2E_TOKEN|"..card.getGUID().."|"..kind) end
    end})
end

function hud()
    if STA2E.loading or STA2E.reconciling then return end
    -- Preserve the known-good top-left toolbar and fleet setup panel.
    local locked,total=lockedCount()
    local progress=STA2E.game.phase=="planning" and (" · "..locked.."/"..total.." LOCKED") or ""
    local bar='<Panel rectAlignment="UpperLeft" offsetXY="58 -62" width="455" height="72" color="#102432EE">'..
        '<Text text="ROUND '..STA2E.game.round..' · '..string.upper(xml(STA2E.game.phase))..progress..'" position="-5 18 0" width="430" height="28" fontSize="20" color="#FFFFFF"/>'..
        '<Button id="advance" onClick="STA2E_PhaseUI" position="-108 -17 0" width="205" height="30" fontSize="15">ADVANCE PHASE</Button>'..
        '<Button id="import" onClick="STA2E_ImportUI" position="108 -17 0" width="205" height="30" fontSize="15">FLEET SETUP</Button></Panel>'
    UI.setXml(bar..fleetPanel()..sidebar()..managePanel()..modifyPanel())
end

local oldRefresh=refresh
refresh=function(s)
    oldRefresh(s)
    if STA2E.ready and STA2E.game then hud() end
end

-- Movement templates are independent of a ship's printed dial.
local function pose(start,move,t)
    local heading=math.rad(start.yaw)
    local forward,side=move.forward or 0,move.side or 0
    local rotation=move.rotate or 0
    local travelRotation=move.finishRotateOnly and 0 or rotation
    local progressForward,progressSide=forward*t,side*t
    if math.abs(travelRotation)>0 and forward>0 and side~=0 then
        -- Bank/turn templates follow a curved path while retaining the measured
        -- endpoint offsets from the original mod. Positive side is ship-left.
        local angle=math.rad(math.abs(travelRotation))
        progressForward=forward*math.sin(angle*t)/math.sin(angle)
        progressSide=side*(1-math.cos(angle*t))/(1-math.cos(angle))
    end
    local sideHeading=heading+math.pi/2
    local x=start.x-math.sin(heading)*progressForward-math.sin(sideHeading)*progressSide
    local z=start.z-math.cos(heading)*progressForward-math.cos(sideHeading)*progressSide
    local yaw=start.yaw-travelRotation*t
    if move.finishRotateOnly and t>=1 then yaw=start.yaw-rotation end
    return {x=x,z=z,yaw=yaw}
end

local function baseShape(object)
    local bounds=object.getBoundsNormalized()
    local size=bounds and bounds.size or {x=2.8,z=2.8}
    return {x=math.max(0.5,size.x/2),z=math.max(0.5,size.z/2)}
end

local function overlaps(a,ashape,b,bshape)
    local yawA,yawB=math.rad(a.yaw),math.rad(b.yaw)
    local axes={{math.cos(yawA),-math.sin(yawA)},{math.sin(yawA),math.cos(yawA)},
        {math.cos(yawB),-math.sin(yawB)},{math.sin(yawB),math.cos(yawB)}}
    local dx,dz=b.x-a.x,b.z-a.z
    local function extent(shape,yaw,ux,uz)
        local rightX,rightZ=math.cos(yaw),-math.sin(yaw)
        local frontX,frontZ=-math.sin(yaw),-math.cos(yaw)
        return shape.x*math.abs(ux*rightX+uz*rightZ)+shape.z*math.abs(ux*frontX+uz*frontZ)
    end
    for _,axis in ipairs(axes) do
        local ux,uz=axis[1],axis[2]
        -- Edge contact is legal. Do not add clearance here: latestLegal already
        -- converges on the last non-overlapping pose, so clearance leaves a
        -- visible gap between bases after a bump.
        if math.abs(dx*ux+dz*uz)>=extent(ashape,yawA,ux,uz)+extent(bshape,yawB,ux,uz) then return false end
    end
    return true
end

local function latestLegal(start,move,shape,obstacles)
    local function legal(t)
        local candidate=pose(start,move,t)
        for _,other in ipairs(obstacles) do
            if overlaps(candidate,shape,other.pose,other.shape) then return false end
        end
        return true
    end
    if legal(1) then return 1 end
    local step=1/40
    for i=39,0,-1 do
        local low=i*step
        if legal(low) then
            local high=low+step
            for _=1,9 do
                local mid=(low+high)/2
                if legal(mid) then low=mid else high=mid end
            end
            return low
        end
    end
    return 0
end

STA2E.Movement={pose=pose,overlaps=overlaps,latestLegal=latestLegal}

local function executeMove(s,color,manualKey)
    if not complete(s) then tell(color,"Deploy / Repair this ship first.");return end
    local key=manualKey or s.state.maneuver
    local move=key and MOVE_DEFS[key]
    if not move then tell(color,"No movement template for "..tostring(key)..".");return end
    if STA2E.pendingMoves[s.instanceId] then tell(color,"This ship is already moving.");return end
    if not manualKey and s.state.status~="revealed" then tell(color,"Reveal the maneuver before executing.");return end
    local base=member(s,"base")
    local p,r=base.getPosition(),base.getRotation()
    local start={x=p.x,z=p.z,yaw=r.y}
    local obstacles={}
    for id,other in pairs(STA2E.ships) do
        if id~=s.instanceId then
            local otherBase=member(other,"base")
            if otherBase then
                local op,orot=otherBase.getPosition(),otherBase.getRotation()
                table.insert(obstacles,{pose={x=op.x,z=op.z,yaw=orot.y},shape=baseShape(otherBase)})
            end
        end
    end
    local stop=latestLegal(start,move,baseShape(base),obstacles)
    s.undo={position={p.x,p.y,p.z},rotation={r.x,r.y,r.z},state=copy(s.state),round=STA2E.game.round}
    STA2E.pendingMoves[s.instanceId]=true
    local wasLocked=base.getLock()
    base.setLock(true)
    local frames=math.max(1,math.ceil(stop*30))
    local frame=0
    local function animate()
        if not obj(base.getGUID()) or not STA2E.ships[s.instanceId] then STA2E.pendingMoves[s.instanceId]=nil;return end
        frame=frame+1
        local q=pose(start,move,stop*frame/frames)
        base.setPosition({q.x,p.y,q.z})
        base.setRotation({r.x,q.yaw,r.z})
        sync(s)
        if frame<frames then Wait.frames(animate,1) else
            base.setLock(wasLocked)
            STA2E.pendingMoves[s.instanceId]=nil
            if manualKey then s.state.maneuver=key;s.state.toolsPage="home" end
            s.state.status="action";s.state.modifyOpen=false
            refresh(s)
            broadcastToAll(s.name.." has executed a maneuver of "..maneuverLabel(s,key)..(stop<0.999 and " (stopped at ship overlap)." or "."),{0.82,0.90,1})
        end
    end
    animate()
end

local function modify(s,color,key)
    if s.state.status~="revealed" then tell(color,"Reveal a maneuver before modifying it.");return end
    key=tostring(key or ""):upper():gsub("%s+","")
    if not MOVE_DEFS[key] then tell(color,"Unknown movement template: "..key);return end
    s.state.maneuver=key
    s.state.modifyOpen=true
    refresh(s)
    broadcastToAll(s.name.." modifies maneuver to "..key..".",{0.82,0.90,1})
end

function STA2E_ModifyChoice(player,value,id)
    if not player then return end
    local color=player.color
    local s=STA2E.ships[STA2E.modifyShip[color]]
    if not s or s.owner~=color or s.state.status~="revealed" then STA2E.modifyShip[color]=nil;hud();return end
    if id=="modify_close" then STA2E.modifyShip[color]=nil;hud();return end
    local key
    if id=="modify_restore" then key=s.state.revealedOriginal
    elseif id=="modify_up" or id=="modify_down" then
        local prefix,speed=(s.state.maneuver or ""):match("^([A-Z]+)(%d+)$")
        if prefix then key=prefix..tostring(tonumber(speed)+(id=="modify_up" and 1 or -1)) end
    else key=id and id:match("^modify_([A-Z]+%d+)$") end
    if not key then tell(color,"No matching maneuver for that adjustment.");return end
    if not MOVE_DEFS[key] then tell(color,"No "..key.." movement template is available.");return end
    STA2E.modifyShip[color]=nil
    modify(s,color,key)
end

function STA2E_SetManeuver(params)
    local s=shipFor(params.object)
    if not s or s.owner~=params.color then return end
    modify(s,params.color,params.key)
end

local oldCommand=STA2E_Command
function STA2E_Command(params)
    local s=shipFor(params.object)
    local cmd=params.command or ""
    if not s or s.owner~=params.color then return oldCommand(params) end
    if STA2E.pendingMoves[s.instanceId] then tell(params.color,"Wait for this ship's movement to finish.");return end
    if cmd=="move" then executeMove(s,params.color);return end
    if cmd=="reveal" then
        if s.state.maneuver then s.state.revealedOriginal=s.state.maneuver end
        oldCommand(params);return
    end
    if cmd=="modify_toggle" then
        if s.state.status~="revealed" then tell(params.color,"Reveal a maneuver before modifying it.");return end
        STA2E.modifyShip[params.color]=s.instanceId
        hud();return
    end
    if cmd=="modify_restore" then modify(s,params.color,s.state.revealedOriginal);return end
    if cmd=="modify_up" or cmd=="modify_down" then
        local prefix,speed=(s.state.maneuver or ""):match("^([A-Z]+)(%d+)$")
        local delta=cmd=="modify_up" and 1 or -1
        if prefix then modify(s,params.color,prefix..tostring(tonumber(speed)+delta)) end
        return
    end
    if cmd=="mark_fired" then s.state.fired=not s.state.fired;refresh(s);return end
    oldCommand(params)
end

local oldPhaseUI=STA2E_PhaseUI
function STA2E_PhaseUI(player)
    oldPhaseUI(player)
    hud()
end
-- Manual ship controls. These remain available when normal phase prompts are
-- irrelevant, while the phase-specific dial remains the default when useful.
local RANGE_SEGMENT=3.94 -- visual TTS-unit guide; compare with the physical ruler
local RANGE_LINE_THICKNESS=0.027 -- approximately one-third of the previous width
local ARC_LINE_THICKNESS=0.034
local GUIDE_TOP_CLEARANCE=0.06
local GUIDE_COLORS={
    Red={{0.50,0.07,0.09},{0.92,0.13,0.16},{1.00,0.42,0.18}},
    Blue={{0.10,0.28,0.64},{0.15,0.51,0.96},{0.25,0.90,1.00}},
}
local TOKEN_CHOICES={
    {"EVA","EVADE"},{"SCN","SCAN"},{"BS","BATTLE"},{"TL","LOCK"},{"CLK","CLOAK"},
    {"REG","REGEN"},{"AUX","AUX"},{"SHIELD","SHIELD"},{"TIME","TIME"},{"DISABLED","DISABLE"},
    {"CRIT","CRIT"},{"DRONE","DRONE"},{"MISSION","MISSION"},{"REINFORCE","REINFORCE"},{"LATINUM","LATINUM"},
}

local function normalizeDialPhase(s)
    s.state=s.state or {status="planning"}
    if STA2E.game.phase~="planning" and s.state.status=="planning" and s.state.maneuver then
        s.state.status="neutral";s.state.toolsPage="home"
        return true
    end
    if (STA2E.game.phase=="combat" or STA2E.game.phase=="end") and not s.state.toolsPage then
        s.state.toolsPage="home"
        return true
    end
    if s.state.maneuver then return false end
    local natural=STA2E.game.phase=="planning" and "planning" or "neutral"
    if s.state.status=="planning" or s.state.status=="neutral" then
        if s.state.status~=natural then
            s.state.status=natural
            s.state.toolsPage=natural=="neutral" and "home" or nil
            return true
        end
        if natural=="neutral" and not s.state.toolsPage then s.state.toolsPage="home";return true end
    end
    return false
end

local function roundedRange(hx,hz,d,y,color)
    local points={}
    for _,corner in ipairs({{hx,-hz,-90},{hx,hz,0},{-hx,hz,90},{-hx,-hz,180}}) do
        for step=0,8 do
            local angle=math.rad(corner[3]+step*90/8)
            table.insert(points,{corner[1]+math.cos(angle)*d,y,corner[2]+math.sin(angle)*d})
        end
    end
    table.insert(points,points[1])
    return {points=points,color=color,thickness=RANGE_LINE_THICKNESS}
end

local function arcLines(halfAngle,center,radii,y,colors)
    local lines={}
    local outer
    for n,radius in ipairs(radii) do
        local points={}
        for step=0,18 do
            local angle=math.rad(center-halfAngle+step*halfAngle*2/18)
            table.insert(points,{math.sin(angle)*radius,y,-math.cos(angle)*radius})
        end
        table.insert(lines,{points=points,color=colors[n],thickness=ARC_LINE_THICKNESS})
        outer=points
    end
    table.insert(lines,{points={{0,y,0},outer[1]},color=colors[3],thickness=ARC_LINE_THICKNESS})
    table.insert(lines,{points={{0,y,0},outer[#outer]},color=colors[3],thickness=ARC_LINE_THICKNESS})
    return lines
end

local function drawShipGuides(s)
    local base=member(s,"base")
    if not base then return end
    local lines={}
    local state=s.state or {}
    local range=tonumber(state.guideRange) or 0
    if range>0 or state.guideArc then
        local bounds=base.getBoundsNormalized()
        local size=bounds and bounds.size or {x=2.8,z=2.8}
        local scale=base.getScale()
        local sx=math.max(0.01,scale and scale.x or 1)
        local sy=math.max(0.01,scale and scale.y or 1)
        local sz=math.max(0.01,scale and scale.z or 1)
        local hx,hz=size.x/(2*sx),size.z/(2*sz)
        -- The collider can be much lower than the visible base top. Use the
        -- renderer bounds so these guides sit above the printed base surface.
        local visual=base.getVisualBoundsNormalized()
        local visualSize=visual and visual.size or size
        local top=(visual and visual.offset and visual.offset.y or 0)+(visualSize.y or 0.4)/2
        local y=(top+GUIDE_TOP_CLEARANCE)/sy
        local bandColor=GUIDE_COLORS[s.owner] or GUIDE_COLORS.Blue
        for n=1,math.min(3,range) do
            table.insert(lines,roundedRange(hx,hz,n*RANGE_SEGMENT/((sx+sz)/2),y,bandColor[n]))
        end
        if state.guideArc then
            local class=definition(s.definitionId)
            local profile=class and class.arc or "90"
            local radii={}
            for n=1,3 do
                radii[n]=math.max(hx,hz)+n*RANGE_SEGMENT/((sx+sz)/2)
            end
            local function addArc(half,center)
                for _,line in ipairs(arcLines(half,center,radii,y,bandColor)) do table.insert(lines,line) end
            end
            if profile=="360" then addArc(180,0) else addArc(profile:match("^180") and 90 or 45,0) end
            if profile:find("rear90",1,true) then addArc(45,180) end
            if profile:find("second30",1,true) then addArc(15,0) end
        end
    end
    base.setVectorLines(lines)
end

local function toolsMarkup(s)
    local page=s.state.toolsPage or "home"
    local phase=string.upper(STA2E.game.phase or "planning")
    local parts={'<Panel visibility="'..s.owner..'" width="700" height="820" color="#102432F2">',
        '<Text text="'..xml(s.name)..' · '..xml(phase)..'" position="0 365 0" width="670" height="36" fontSize="23" color="#FFFFFF"/>'}
    local function add(id,label,x,y,shade,width)
        table.insert(parts,dialButton(id,label,x,y,shade,width))
    end
    if page=="tokens" then
        table.insert(parts,'<Text text="SPAWN TOKEN BY BASE" position="0 305 0" width="650" height="30" fontSize="19" color="#FFD86B"/>')
        for i,choice in ipairs(TOKEN_CHOICES) do
            local x=-250+((i-1)%5)*125
            local y=225-math.floor((i-1)/5)*72
            add("tool_token_"..choice[1],choice[2],x,y,"#284A66",115)
        end
        add("tool_home","BACK",0,-315,"#526777",260)
    elseif page=="moves" then
        local keys={}
        for key in pairs(MOVE_DEFS) do table.insert(keys,key) end
        table.sort(keys)
        local pageNo=math.max(1,math.floor(tonumber(s.state.toolsMovePage) or 1))
        local pages=math.max(1,math.ceil(#keys/24))
        pageNo=math.min(pageNo,pages)
        table.insert(parts,'<Text text="MANUAL MANEUVER · '..pageNo..'/'..pages..'" position="0 305 0" width="650" height="30" fontSize="19" color="#FFD86B"/>')
        for slot=1,24 do
            local key=keys[(pageNo-1)*24+slot]
            if key then
                local x=-240+((slot-1)%4)*160
                local y=235-math.floor((slot-1)/4)*65
                add("tool_move_"..key,key,x,y,"#284A66",145)
            end
        end
        if pageNo>1 then add("tool_prev","PREV",-160,-235,"#526777",145) end
        if pageNo<pages then add("tool_next","NEXT",160,-235,"#526777",145) end
        add("tool_home","BACK",0,-315,"#526777",260)
    elseif page=="arcs" then
        local class=definition(s.definitionId)
        local profile=class and class.arc or "90"
        table.insert(parts,'<Text text="ARCS '..xml(profile)..' · RANGE GUIDE" position="0 295 0" width="650" height="30" fontSize="19" color="#FFD86B"/>')
        add("tool_arc_toggle",s.state.guideArc and "HIDE ARCS" or "SHOW ARCS",0,190,"#285779",350)
        for n=1,3 do add("tool_range_"..n,"RANGE "..n,(n-2)*205,80,"#375A78",190) end
        add("tool_clear_guides","CLEAR GUIDES",0,-20,"#863B3B",350)
        table.insert(parts,'<Text text="Visual ruler guide; use physical templates for close calls." position="0 -125 0" width="660" height="55" fontSize="16" color="#C8D9E8"/>')
        add("tool_home","BACK",0,-315,"#526777",260)
    else
        table.insert(parts,'<Text text="SHIP CONTROLS" position="0 300 0" width="650" height="36" fontSize="24" color="#FFD86B"/>')
        add("tool_tokens","TOKENS",0,205,"#285779",400)
        add("tool_moves","ANY MANEUVER",0,120,"#256348",400)
        add("tool_arcs","ARCS & RANGE",0,35,"#375A78",400)
        add("tool_undo","UNDO MOVE",0,-65,"#526777",300)
        if s.state.status~="neutral" then add("tool_close","PHASE SCREEN",0,-315,"#526777",300) end
    end
    table.insert(parts,'</Panel>')
    table.insert(parts,'<Panel visibility="'..publicVisibility(s.owner)..'" width="620" height="180" color="#102432F2"><Text text="'..xml(s.name)..'" position="0 42 0" width="600" height="35" fontSize="24" color="#FFFFFF"/><Text text="'..xml(phase)..' · SHIP CONTROL" position="0 -12 0" width="600" height="35" fontSize="19" color="#FFFFFF"/></Panel>')
    local markup=table.concat(parts):gsub('<Button ', '<Button textColor="#FFFFFF" ')
    local root='<Panel id="sta2e_dashboard" width="700" height="820" position="0 0 -120" rotation="0 0 180" scale="0.4 0.4 1" color="#00000000" raycastTarget="false">'
    return root..markup..'</Panel>'
end

local phaseRender=render
render=function(s)
    if not s.state or not s.state.toolsPage then phaseRender(s);return end
    local dial=member(s,"dial")
    if not dial then phaseRender(s);return end
    dial.UI.setXml(s.state.dialOpen==true and toolsMarkup(s) or "")
    if dial.call then dial.call("STA2E_SetDisplay",{dialOpen=s.state.dialOpen==true,status=s.state.status,maneuver=s.state.maneuver}) end
    local card=obj(s.cardGUID)
    if card then card.UI.setXml("") end
end

local phaseCommand=STA2E_Command
function STA2E_Command(params)
    local cmd=params.command or ""
    if cmd:sub(1,5)~="tool_" then return phaseCommand(params) end
    local s=shipFor(params.object)
    if not s or s.owner~=params.color then return end
    if cmd=="tool_close" then
        s.state.toolsPage=nil
    elseif cmd=="tool_home" then
        s.state.toolsPage="home"
    elseif cmd=="tool_tokens" then
        s.state.toolsPage="tokens"
    elseif cmd=="tool_moves" then
        s.state.toolsPage="moves";s.state.toolsMovePage=1
    elseif cmd=="tool_arcs" then
        s.state.toolsPage="arcs"
    elseif cmd=="tool_prev" then
        s.state.toolsMovePage=math.max(1,(s.state.toolsMovePage or 1)-1)
    elseif cmd=="tool_next" then
        s.state.toolsMovePage=(s.state.toolsMovePage or 1)+1
    elseif cmd=="tool_undo" then
        phaseCommand({object=params.object,color=params.color,command="undo"});return
    elseif cmd=="tool_arc_toggle" then
        s.state.guideArc=not s.state.guideArc;drawShipGuides(s)
    elseif cmd=="tool_clear_guides" then
        s.state.guideArc=false;s.state.guideRange=0;drawShipGuides(s)
    elseif cmd:match("^tool_range_[123]$") then
        s.state.guideRange=tonumber(cmd:sub(-1));drawShipGuides(s)
    elseif cmd:sub(1,11)=="tool_token_" then
        local key=cmd:sub(12)
        if not ACTION_BAGS[key] then tell(params.color,"That token bag is unavailable.");return end
        spawnActionToken(s,key)
    elseif cmd:sub(1,10)=="tool_move_" then
        local key=cmd:sub(11)
        if not MOVE_DEFS[key] then tell(params.color,"Unknown maneuver.");return end
        executeMove(s,params.color,key);return
    else return end
    refresh(s)
end

local phaseReconcile=STA2E_Reconcile
function STA2E_Reconcile()
    phaseReconcile()
    for _,s in pairs(STA2E.ships) do
        if normalizeDialPhase(s) then refresh(s) end
        if s.state.guideArc or (s.state.guideRange or 0)>0 then drawShipGuides(s) end
    end
end

local phaseAdvance=STA2E_PhaseUI
function STA2E_PhaseUI(player)
    local before=STA2E.game.phase
    phaseAdvance(player)
    if STA2E.game.phase==before then return end
    for _,s in pairs(STA2E.ships) do
        s.state.toolsPage=nil
        normalizeDialPhase(s)
        refresh(s)
    end
end
function onLoad(saved)
    local state=decode(saved)
    STA2E.game=(state and state.schemaVersion==1 and state.game) or {round=1,phase="planning",nextId=100,fleets={}}
    STA2E.game.rulesMode="open"
    STA2E.ships={};STA2E.pending={};STA2E.imports={};STA2E.fleetText={};STA2E.fleetStatus={};STA2E.fleetPlans={};STA2E.fleetColor=nil
    STA2E.ready=false;STA2E.loading=true
    CATALOG={};CATALOG_ORDINAL={}
    UI.setXml('<Panel rectAlignment="UpperLeft" offsetXY="58 -62" width="455" height="50" color="#102432EE"><Text color="#FFFFFF" fontSize="20">Preparing fleets...</Text></Panel>')
    local started=Time.time
    local jobIndex,cardIndex=1,1
    local function step()
        local ok,err=pcall(function()
            local job=startupJobs and startupJobs[jobIndex]
            if job then
                local values=JSON.decode(job.json)
                for key,value in pairs(values) do
                    job.target[job.offset>=0 and (job.offset+key) or key]=value
                end
                job.json=nil
                jobIndex=jobIndex+1
                Wait.frames(step,1)
                return
            end
            local cards=CATALOG_DATA.cards or {}
            if cardIndex<=#cards then
                local last=math.min(cardIndex+149,#cards)
                for i=cardIndex,last do
                    local card=cards[i]
                    local asset=card.assetSheet and CATALOG_DATA.assetSheets and CATALOG_DATA.assetSheets[card.assetSheet]
                    if asset then
                        card.cardImage=asset.cardImage;card.cardBack=asset.cardBack;card.sheet=card.sheet or {}
                        card.sheet.width=asset.width;card.sheet.height=asset.height;card.sheet.uniqueBack=asset.uniqueBack
                    end
                    if card.publishedFace then
                        card.cardImage=card.publishedFace
                        if not card.dualSided then card.cardBack=CATALOG_DATA.genericCardBack end
                        card.sheet=nil
                    end
                    CATALOG[card.id]=card;CATALOG_ORDINAL[card.id]=i
                end
                cardIndex=last+1
                Wait.frames(step,1)
                return
            end
            STA2E.ready=true
            STA2E_Reconcile()
            STA2E.loading=false
            hud()
            print(string.format("STA2E startup: %.3fs elapsed after onLoad (includes frame yields; excludes script compilation)",Time.time-started))
            startupJobs=nil
        end)
        if not ok then
            STA2E.ready=false;STA2E.loading=true;STA2E.reconciling=false
            print("STA2E startup failed: "..tostring(err))
            UI.setXml('<Panel rectAlignment="UpperLeft" offsetXY="58 -62" width="455" height="70" color="#642B2BEE"><Text color="#FFFFFF" fontSize="18">Fleet startup failed. See scripting log and reload the save.</Text></Panel>')
        end
    end
    Wait.frames(step,10)
end
function onSave() return JSON.encode({schemaVersion=1,game=STA2E.game}) end
function onObjectDrop(color,object)
    local s=shipFor(object);local m=metadata(object)
    if s and m and (m.role=="base" or m.role=="baseModel") then Wait.frames(function()sync(s)end,1) end
end
function onObjectDestroy(object)
    if not STA2E.ready then return end
    local m=metadata(object)
    if not m then return end
    local s=STA2E.ships[m.instanceId]
    if not s then return end
    if m.role=="card" and s.cardGUID==object.getGUID() then STA2E.ships[m.instanceId]=nil;STA2E.pending[m.instanceId]=nil
    elseif m.role=="baseModel" then s.refs.base=nil;s.refs.model=nil;refresh(s)
    elseif m.role=="base" and s.refs.base==object.getGUID() then
        local model=member(s,"model")
        s.refs.base=nil;s.refs.model=nil
        STA2E.pending[m.instanceId]=nil
        if model then model.destruct() end
        refresh(s)
    elseif s.refs[m.role]==object.getGUID() then s.refs[m.role]=nil;refresh(s) end
end
